        groups = []
        group = ''
        open_count = 0

        for char in paren_string:
            if char == '(':
                open_count += 1
                if open_count == 1:
                    group += char
            elif char == ')':
                open_count -= 1
                if open_count == 0:
                    group += char
                    groups.append(group)
                    group = ''
            else:
                if open_count > 0:
                    group += char

        return groups

    def remove_spaces(groups):
        return [group.replace(' ', '') for group in groups]

    def split_groups(groups):
        return [group for group in groups]

    extracted_groups = extract_groups(paren_string)
    cleaned_groups = remove_spaces(extracted_groups)
    distinct_groups = split_groups(cleaned_groups)

    return distinct_groups

